const languageKey = 'soft999.language.v1';
const validLanguages = ['ru', 'uk', 'en'];
const textSources = new WeakMap();
const attributeSources = new WeakMap();
function translated(value, language) {
  if (!value.trim()) return value;
  const source = value.trim();
  return value.match(/^\s*/)[0] + (language === 'ru' ? source : (dictionaries[language][source] || source)) + value.match(/\s*$/)[0];
}
function translateNode(node, language) {
  if (node.parentElement?.closest('script,style,[data-no-i18n]')) return;
  const previous = textSources.get(node);
  const source = previous && node.nodeValue === previous.rendered ? previous.source : node.nodeValue;
  const rendered = translated(source, language);
  textSources.set(node, {source, rendered});
  if (node.nodeValue !== rendered) node.nodeValue = rendered;
}
function apply(root, language) {
  if (root.nodeType === Node.TEXT_NODE) { translateNode(root, language); return; }
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) translateNode(node, language);
  const elements = root.nodeType === Node.ELEMENT_NODE ? [root, ...root.querySelectorAll('*')] : [];
  for (const element of elements) {
    if(element.closest('[data-no-i18n]')) continue;
    let records = attributeSources.get(element);
    if(!records){records = new Map();attributeSources.set(element,records);}
    for (const attribute of ['placeholder','aria-label','title','content']) {
      if(!element.hasAttribute(attribute)) continue;
      const current = element.getAttribute(attribute), previous = records.get(attribute);
      const source = previous && current === previous.rendered ? previous.source : current;
      const rendered = translated(source, language);
      records.set(attribute,{source,rendered});
      if(current !== rendered) element.setAttribute(attribute,rendered);
    }
  }
}
function preferredLanguage() {
  for (const item of navigator.languages?.length ? navigator.languages : [navigator.language || 'en']) {
    const short = item.toLowerCase().split('-')[0];
    if(validLanguages.includes(short)) return short;
  }
  return 'en';
}
export function initLocale() {
  let saved = null;
  try { saved = localStorage.getItem(languageKey); } catch {}
  let language = validLanguages.includes(saved) ? saved : preferredLanguage();
  const picker = document.querySelector('#language-select');
  const originalTitle = document.title;
  const setLanguage = (next, persist = true) => {
    if(!validLanguages.includes(next)) return;
    language = next;
    document.documentElement.lang = next;
    document.title = translated(originalTitle,next);
    apply(document.body,next);
    for(const element of document.head.querySelectorAll('meta[content]')) apply(element,next);
    if(picker) picker.value = next;
    if(persist){try{localStorage.setItem(languageKey,next);}catch{}}
  };
  picker?.addEventListener('change',()=>setLanguage(picker.value));
  setLanguage(language,false);
  const observer = new MutationObserver(records=>{
    for(const record of records){
      if(record.type === 'characterData') translateNode(record.target,language);
      else if(record.type === 'childList'){
        for(const node of record.addedNodes) if(node.nodeType === Node.ELEMENT_NODE || node.nodeType === Node.TEXT_NODE) apply(node,language);
      }else if(record.type === 'attributes') apply(record.target,language);
    }
  });
  observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title','content']});
}

